<?php require_once __DIR__.'/../_init.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM love_story WHERE id=?')->execute([(int)$_GET['delete']]);redirect('index.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('INSERT INTO love_story(tanggal_label,judul,cerita,urutan) VALUES(?,?,?,?)')->execute([trim($_POST['tanggal_label']),trim($_POST['judul']),trim($_POST['cerita']),(int)$_POST['urutan']]);redirect('index.php');}$rows=$pdo->query('SELECT * FROM love_story ORDER BY urutan,id')->fetchAll();admin_header('Love Story');?><div class="admin-card"><h1>Love Story</h1><form method="post" class="form"><?=csrf_field()?><div class="grid2"><input name="tanggal_label" placeholder="25 AGUSTUS 2023" required><input name="judul" placeholder="Awal Bertemu"></div><textarea name="cerita" placeholder="Cerita..." required></textarea><input type="number" name="urutan" value="1"><button class="btn">Tambah</button></form></div><div class="admin-card"><table class="table"><tr><th>Tanggal</th><th>Judul</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal_label'])?></td><td><?=e($r['judul'])?></td><td><a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></td></tr><?php endforeach;?></table></div><?php admin_footer();?>
